// Finance Pack tools definition
const FINANCE_PACK_TOOLS = [
  {
    name: 'gravito.reviewTradingThesis',
    description: 'Review and validate a trading thesis or research analyst output. Checks for forbidden claims, citation quality, scenario coverage, and confidence alignment. Returns governance decision with score and issues.',
    inputSchema: {
      type: 'object',
      properties: {
        thesis: { type: 'string', description: 'The trading thesis or research output to review' },
        ticker: { type: 'string', description: 'Stock ticker symbol if applicable' },
        asset_class: { type: 'string', enum: ['equity', 'fixed_income', 'commodity', 'crypto', 'forex', 'derivative'], default: 'equity' },
        thesis_type: { type: 'string', enum: ['long', 'short', 'neutral', 'pair_trade'], default: 'long' },
        citations: { type: 'array', items: { type: 'object', properties: { claim: { type: 'string' }, source: { type: 'string' }, date: { type: 'string' } } } },
      },
      required: ['thesis'],
    },
  },
  {
    name: 'gravito.reviewTradeProposal',
    description: 'Gate trade execution by reviewing position sizing, risk constraints, evidence quality, and rationale. Returns approval decision with required actions before execution.',
    inputSchema: {
      type: 'object',
      properties: {
        action: { type: 'string', enum: ['buy', 'sell', 'short', 'cover', 'rebalance'] },
        ticker: { type: 'string' },
        quantity: { type: 'number' },
        position_size_pct: { type: 'number', description: 'Position size as % of portfolio' },
        rationale: { type: 'string', description: 'Why this trade' },
        stop_loss: { type: 'number', description: 'Stop loss price or %' },
        take_profit: { type: 'number', description: 'Take profit price or %' },
        time_horizon: { type: 'string', description: 'Expected holding period' },
        risk_reward_ratio: { type: 'number' },
      },
      required: ['action', 'ticker', 'rationale'],
    },
  },
  {
    name: 'gravito.reviewStrategyChange',
    description: 'Audit strategy code changes (PineScript, Python, etc.) for backtest requirements, overfit detection, and deployment readiness. Returns deployment recommendation.',
    inputSchema: {
      type: 'object',
      properties: {
        strategy_name: { type: 'string' },
        change_type: { type: 'string', enum: ['parameter', 'logic', 'signal', 'risk_rule', 'new_strategy'] },
        description: { type: 'string', description: 'What changed and why' },
        code_diff: { type: 'string', description: 'The actual code change' },
        backtest_results: { type: 'object', properties: { sharpe_ratio: { type: 'number' }, max_drawdown: { type: 'number' }, win_rate: { type: 'number' }, profit_factor: { type: 'number' }, total_trades: { type: 'number' }, period: { type: 'string' } } },
        baseline_comparison: { type: 'object', properties: { baseline_sharpe: { type: 'number' }, new_sharpe: { type: 'number' }, improvement_pct: { type: 'number' } } },
      },
      required: ['strategy_name', 'change_type', 'description'],
    },
  },
  {
    name: 'gravito.trackTradingOutcome',
    description: 'Track trade outcomes for learning and attribution. Records P&L, thesis accuracy, and generates learning insights for future improvement.',
    inputSchema: {
      type: 'object',
      properties: {
        trade_id: { type: 'string' },
        ticker: { type: 'string' },
        entry_price: { type: 'number' },
        exit_price: { type: 'number' },
        pnl: { type: 'number' },
        pnl_pct: { type: 'number' },
        holding_period_days: { type: 'number' },
        thesis_accuracy: { type: 'string', enum: ['correct', 'partially_correct', 'incorrect', 'too_early'] },
        original_rationale: { type: 'string' },
        lessons_learned: { type: 'string' },
      },
      required: ['trade_id', 'ticker', 'entry_price'],
    },
  },
];

// Combine all tools and deduplicate by name (keep first occurrence)
const ALL_TOOLS_RAW = [
  ...GRAVITO_TOOLS, 
  ...FINANCE_PACK_TOOLS,
  ...compliancePackTools,
  ...outboundPackTools,
  ...agentRuntimePackTools,
  ...CREATIVE_PARTNER_TOOLS, // Put last since it has duplicates with GRAVITO_TOOLS
  // Mandatory Enforcement tools
  {
    name: 'gravito.enforcementStats',
    description: 'Get statistics on all 4 enforcement choke points (pre-creation, during-creation, pre-commit, pre-release). Shows total checks, pass rate, blocked count, and average score.',
    inputSchema: { type: 'object', properties: {}, required: [] },
  },
  {
    name: 'gravito.enforcementLog',
    description: 'Get the full enforcement audit trail. Filter by choke point, pass/fail status, and limit.',
    inputSchema: {
      type: 'object',
      properties: {
        chokePoint: { type: 'string', enum: ['pre-creation', 'during-creation', 'pre-commit', 'pre-release'] },
        passed: { type: 'boolean' },
        limit: { type: 'number' },
      },
      required: [],
    },
  },
