      },
      required: ['prompt'],
    },
  },
  {
    name: 'gravito.toolHealth',
    description: 'Self-discovery endpoint for AI consumers. Returns which tools are functional, what schemas they expect, and their health status. Use this first to understand what tools are available and how to call them.',
    inputSchema: {
