/**
 * Optional operator-focused catalog for MCP tools/list.
 * Set MCP_TOOL_PACK=control-tower to exclude niche packs (e.g. finance trading) from discovery.
 */
function resolveToolsForMcpList(): typeof ALL_TOOLS {
  const pack = process.env.MCP_TOOL_PACK?.trim().toLowerCase();
  if (!pack || pack === 'all' || pack === 'full') {
    return ALL_TOOLS;
  }
  if (pack === 'control-tower' || pack === 'tower') {
    const excludeFinanceTrading = /^(gravito\.(reviewTradingThesis|reviewTradeProposal|reviewStrategyChange|trackTradingOutcome))$/;
    const filtered = ALL_TOOLS.filter(
      (t) => typeof t.name === 'string' && t.name.startsWith('gravito.') && !excludeFinanceTrading.test(t.name),
    );
    return filtered.length > 0 ? filtered : ALL_TOOLS;
  }
  return ALL_TOOLS;
}

