            result = await safeTool(async () => {
              const r = await handlePromoteExperiment(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'auto_remediate': {
            const { handleAutoRemediate } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleAutoRemediate(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'list_deployments': {
            const { handleListDeployments } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleListDeployments(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'get_deployment_status': {
            const { handleGetDeploymentStatus } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleGetDeploymentStatus();
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'get_scan_results': {
            const { handleGetScanResults } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleGetScanResults(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }

          default: {
            // Bridge fallback - route to unified tool bridge for all other tools
            result = await safeTool(async () => {
              const bridge = getUnifiedToolBridge();
              const toolName = name?.replace('gravito.', '') || name;
              const bridgeResult = await bridge.invokeTool(toolName, normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(bridgeResult) }] };
            });
          }
        }
      }
        break;

      default:
        return res.json({
          jsonrpc: '2.0',
          id,
          error: { code: -32601, message: `Method not found: ${method}` },
        });
    }

    // Log successful request
    const toolName = method === 'tools/call' ? (params?.name || 'unknown') : method;
    const responseText = JSON.stringify(result);
    logUsage({
      apiKey,
      ipAddress: clientIp,
      toolName,
      method: method || 'unknown',
      success: true,
      responseTimeMs: Date.now() - requestStart,
      estimatedInputTokens: estimateTokens(JSON.stringify(params || {})),
      estimatedOutputTokens: estimateTokens(responseText),
      userAgent,
    });

    // Emit real-time governance event
    const isBlocked = responseText.includes('"block_release":true') || responseText.includes('"blocked":true');
    const scoreMatch = responseText.match(/"score"\s*:\s*(\d+)/);
    emitGovernanceEvent({
      type: isBlocked ? 'block' : 'approval',
      source: 'mcp',
      tool: toolName,
      score: scoreMatch ? parseInt(scoreMatch[1]) : undefined,
      blocked: isBlocked,
      details: `${toolName} via MCP`,
      apiKeyPrefix: apiKey?.substring(0, 12),
      durationMs: Date.now() - requestStart,
    });

    // ================================================================
    // GOVERNED USAGE METERING — increment monthly counter for billing
    // Only for tools/call (actual governance checks), not tools/list
    // ================================================================
    if (method === 'tools/call') {
      const authUserId = ((req as unknown as Record<string, unknown>)).authUserId as number | undefined;
      // Fire-and-forget: don't block the response on metering
      (async () => {
        try {
          let stripeCustomerId: string | undefined;
          let stripeSubscriptionId: string | undefined;
          let plan: string | undefined;
          if (authUserId) {
            const sub = await getSubscriptionByUserId(authUserId);
            if (sub) {
              stripeCustomerId = sub.stripeCustomerId || undefined;
              stripeSubscriptionId = sub.stripeSubscriptionId || undefined;
              plan = sub.plan || undefined;
            }
          }
          await recordGovernedCheck({
            apiKeyPrefix: apiKey?.substring(0, 16),
            userId: authUserId,
            stripeCustomerId,
            stripeSubscriptionId,
            plan,
            toolName,
            success: true,
            blocked: isBlocked,
            responseTimeMs: Date.now() - requestStart,
            estimatedInputTokens: estimateTokens(JSON.stringify(params || {})),
            estimatedOutputTokens: estimateTokens(responseText),
            ipAddress: clientIp,
            userAgent,
          });
        } catch (meterErr) {
          generalLog.error('[MCP] Usage metering error (non-fatal):', meterErr);
        }
      })();
    }

    // Record latency for Prometheus metrics
    recordLatencyObservation('request', Date.now() - requestStart);
    res.json({ jsonrpc: '2.0', id, result });

  } catch (error) {
    generalLog.error('[MCP JSON-RPC] Error:', error);

    // Log failed request
    const toolName = req.body?.method === 'tools/call' ? (req.body?.params?.name || 'unknown') : (req.body?.method || 'unknown');
    logUsage({
      apiKey,
      ipAddress: clientIp,
      toolName,
      method: req.body?.method || 'unknown',
      success: false,
      errorMessage: error instanceof Error ? error.message : 'Internal error',
      responseTimeMs: Date.now() - requestStart,
      userAgent,
    });

    // Emit error event
    emitGovernanceEvent({
      type: 'error',
      source: 'mcp',
      tool: toolName,
      details: error instanceof Error ? error.message : 'Internal error',
      apiKeyPrefix: apiKey?.substring(0, 12),
      durationMs: Date.now() - requestStart,
    });

    // NEVER expose raw error.message to customer — use generic message only
    res.json({
      jsonrpc: '2.0',
      id: req.body?.id,
      error: { code: -32603, message: 'Request could not be processed — please retry or contact support' },
    });
  }
});

// ============================================================================
// HEALTH CHECK (Unauthenticated - includes auth metadata)
// ============================================================================

mcpRouter.get('/health', (req: Request, res: Response) => {
  ensureServerInitialized();
  const server = getGravitoMCPServer();

  // Collect circuit breaker metrics
  const cbMetrics = getAllCircuitBreakerMetrics();
  const openBreakers = cbMetrics.filter(m => m.state === 'OPEN');
  const halfOpenBreakers = cbMetrics.filter(m => m.state === 'HALF_OPEN');
  const totalCalls = cbMetrics.reduce((sum, m) => sum + m.totalCalls, 0);
  const totalFallbacks = cbMetrics.reduce((sum, m) => sum + m.fallbacksUsed, 0);
  const fallbackRate = totalCalls > 0 ? Math.round((totalFallbacks / totalCalls) * 10000) / 100 : 0;

  // Determine overall status
  // degraded: any circuit breaker is OPEN or fallback rate > 10%
  // down: all circuit breakers are OPEN
  const allOpen = cbMetrics.length > 0 && cbMetrics.every(m => m.state === 'OPEN');
  const anyOpen = openBreakers.length > 0;
  const status = allOpen ? 'down' : (anyOpen || fallbackRate > 10) ? 'degraded' : 'ok';

  res.json({
    name: GRAVITO_MCP_SERVER_NAME,
    transport: 'http',
    status,
    tools_count: ALL_TOOLS.length,
    // Explicitly declare auth type (NOT OAuth) - critical for Manus
    auth: {
      type: 'api_key',
      in: 'header',
      header: 'Authorization',
      format: 'Bearer <token>',
      oauth: false,
      requires_login: false,
    },
    // Operational health
    circuitBreakers: {
      total: cbMetrics.length,
      open: openBreakers.length,
      halfOpen: halfOpenBreakers.length,
      closed: cbMetrics.length - openBreakers.length - halfOpenBreakers.length,
      openNames: openBreakers.map(m => m.name),
    },
    fallbackRate: `${fallbackRate}%`,
    regulatedFailClosed: true, // Always true — regulated surfaces never degrade
    retryPolicy: {
      maxAttempts: 3,
      backoffMs: [1000, 2000, 4000],
      retryableErrors: ['external_authority_unavailable', 'upstream_timeout', 'degraded_mode'],
    },
    timestamp: new Date().toISOString(),
  });
});

