          }
          case 'gravito.createExperiment': {
            result = await safeTool(async () => {
              const creativeService = getCreativePartnerService();
              return { content: [{ type: 'text', text: JSON.stringify(await creativeService.createExperiment(unsafeCast(normalizedArgs, "boundary cast"))) }] };
            });
            break;
          }
          case 'gravito.publishPatch': {
            result = await safeTool(async () => {
              const creativeService = getCreativePartnerService();
              return { content: [{ type: 'text', text: JSON.stringify(await creativeService.publishPatch(unsafeCast(normalizedArgs, "boundary cast"))) }] };
            });
